+
+		StringName node_type = scene_state->get_node_type(i);
+
+		if (!_is_node_visible(scene_state, i)) {
+			continue; // Do not count nodes that are not visible, or under a viewport.
+		}
+		if (ClassDB::is_parent_class(node_type, "Control")) {
+			c2d++;
