+		if (ClassDB::is_parent_class(node_type, "Node2D")) {
+			c2d++;
+		}
+		if (ClassDB::is_parent_class(node_type, "Node3D")) {
+			c3d++;
+		}
+		if (ClassDB::is_parent_class(node_type, "Light3D")) {
+			c3d_light++;
+		}
+	}
