+EditorPackedScenePreviewPlugin::~EditorPackedScenePreviewPlugin() {
+	// Just in case we do not freeze the editor
+	abort_mutex->unlock();
+	construct_mutex->unlock();
+
+	memdelete(abort_mutex);
+	memdelete(construct_mutex);
+}
