+// Try get node property in scene state as common Variant, if failed, returns `p_default_value`
+Variant EditorPackedScenePreviewPlugin::_scene_get_property_value(Ref<SceneState> p_state, int &p_node_idx, const StringName &p_property_name, const Variant &p_default_value) const {
+	bool property_found, node_deferred;
+	ERR_FAIL_COND_V_MSG(p_property_name == "", p_default_value, "`p_property_name is not defined, returning default value.`");
+
+	if (p_node_idx > p_state->get_node_count() - 1) {
+		ERR_PRINT(vformat("`p_node_idx=%d` is out of bounds (p_state->get_node_count() == %d), returning default value.", p_node_idx, p_state->get_node_count()));
+		return p_default_value;
+	}
+
+	Variant value = p_state->get_property_value(p_node_idx, p_property_name, property_found, node_deferred);
+	if (property_found && value.get_type() != Variant::Type::NIL) {
+		return value;
+	}
+	return p_default_value;
+}
