+// Get the accumulated file size in bytes of all the resources a scene has used
+uint64_t EditorPackedScenePreviewPlugin::_get_accumulated_file_size(const String &p_path) const {
+	uint64_t acc_size = 0;
+
+	Ref<FileAccess> fs = FileAccess::open(p_path, FileAccess::ModeFlags::READ);
+	String file_str;
+	if (fs.is_null()) {
+		return acc_size;
+	}
+
+	acc_size += fs->get_length();
+
+	// Try read scene file
+	if (p_path.ends_with(".tscn")) {
+		file_str = fs->get_as_text();
+	}
+
+	// TODO; FIXME - No idea how to read binary .scn to text here, some one help (2025-10-26)
+
+	if (file_str == "") {
+		fs->close();
+		return acc_size;
+	}
+
+	PackedStringArray file_lines = file_str.split("\n", false);
+	Vector<int> ext_res_lines;
+	Vector<int> sub_res_lines;
+
+	// Fetch resource lines
+	for (int i = 0; i < file_lines.size(); i++) {
+		String line = file_lines[i];
+		if (line.begins_with("[ext_resource")) {
+			ext_res_lines.push_back(i);
+		}
+		if (line.begins_with("[sub_resource")) {
+			sub_res_lines.push_back(i);
+		}
+	}
+
+	// Handle external resources
+	for (int i = 0; i < ext_res_lines.size(); i++) {
+		String line = file_lines[ext_res_lines[i]];
+
+		// Read resource attributes
+		PackedStringArray segments = line.split(" ");
+		String resource_path;
+		String resource_type;
+		for (int j = 0; j < segments.size(); j++) {
+			if (segments[j].begins_with("path=\"")) {
+				resource_path = segments[j].trim_prefix("path=\"").split("\"", true, 1)[0];
+			}
+			if (segments[j].begins_with("type=\"")) {
+				resource_type = segments[j].trim_prefix("type=\"").split("\"", true, 1)[0];
+			}
+		}
+
+		if (resource_path == "") {
+			continue;
+		}
+
+		// Append file size
+		if (resource_type == "PackedScene") {
+			acc_size += _get_accumulated_file_size(resource_path);
+		} else {
+			acc_size += FileAccess::get_size(resource_path);
+		}
+		continue;
+	}
+
+	// Handle internal resources
+	for (int i = 0; i < sub_res_lines.size(); i++) {
+		String line = file_lines[sub_res_lines[i]];
+
+		// Find the line attribute of `load_path` (= internal resource path)
+		PackedStringArray segments = line.split(" ");
+		int search_idx = sub_res_lines[i] + 1;
+		String next_line;
+		while (!next_line.begins_with("[") && search_idx <= file_lines.size() - 1) {
+			next_line = file_lines[sub_res_lines[i] + 1];
+			if (next_line.begins_with("load_path")) { // We are looking for resource paths
+				break;
+			}
+			search_idx += 1;
+		}
+		if (!next_line.begins_with("load_path") || next_line.split(" = ").size() < 2) {
+			continue; // Failed to find resource path
+		}
+
+		String resource_path = next_line.split(" = ")[1].replace("\"", "");
+
+		// Record file size
+		acc_size += FileAccess::get_size(resource_path);
+		continue;

