+bool EditorPackedScenePreviewPlugin::_get_aborted() const {
+	abort_mutex->lock();
+	bool value = aborted;
+	abort_mutex->unlock();
+	return value;
+}
+
+void EditorPackedScenePreviewPlugin::_set_scene_construct_done(bool p_done) const {
+	construct_mutex->lock();
+	scene_construct_done = p_done;
+	construct_mutex->unlock();
+}
+
+bool EditorPackedScenePreviewPlugin::_get_scene_construct_done() const {
+	construct_mutex->lock();
+	bool value = scene_construct_done;
+	construct_mutex->unlock();
+	return value;
+}
